{"file_path":"tests/test_spec.py","content":"import pytest

from sales_dashboard.loader import dedupe_sessions, daily_conversion_counts, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def session(id_, day, converted):
    return {"id": id_, "day": day, "converted": converted}


def test_conversion_rate_none_counts_in_denominator():
    assert conversion_rate([session("a", 1, True), session("b", 1, None)]) == 0.5
    assert conversion_rate([session("a", 1, None)]) == 0.0
    assert conversion_rate([]) == 0.0


def test_pooled_rate_is_weighted_by_sessions_and_handles_empty_groups():
    groups = {"small": [session("a", 1, True)],
              "large": [session(str(i), 1, False) for i in range(3)],
              "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({}) == 0.0
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_window_boundaries():
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 1) == 3
    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 8) == 6
    assert conversions_in_window([], 3) == 0


def test_parse_values_whitespace_and_skipped_lines():
    lines = ["\n", "  # comment, not, a, record", " a , 1 , 1 ",
             "b, 2, 0", " c, 3,   ", "   "]
    assert parse_session_log(lines) == [session("a", 1, True),
                                        session("b", 2, False),
                                        session("c", 3, None)]


@pytest.mark.parametrize("bad_line", ["a,1", "a,1,1,extra", "a,no,1", "a,1,yes"])
def test_parse_errors_include_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 3\b"):
        parse_session_log(["", " # skipped", bad_line])


def test_dedupe_keeps_last_duplicate_and_sorts_by_day_then_id():
    events = [session("a", 1, True), session("b", 2, True),
              session("a", 2, None), session("c", 1, False),
              session("b", 2, False)]
    assert dedupe_sessions(events) == [events[3], events[2], events[4]]
    assert dedupe_sessions([]) == []


def test_daily_counts_fill_gaps_and_ignore_outside_range():
    events = [session("a", 1, True), session("b", 3, True),
              session("c", 3, True), session("d", 2, None),
              session("e", 4, True), session("f", 3, False)]
    assert daily_conversion_counts(events, 1, 3) == [1, 0, 2]
    assert daily_conversion_counts([], 2, 4) == [0, 0, 0]
    assert daily_conversion_counts(events, 3, 2) == []


def test_campaign_summary_uses_calendar_days_and_nonempty_groups():
    groups = {"a": [session("a", 1, True), session("b", 3, False),
                    session("c", 3, False)], "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 1}
    assert campaign_summary(groups, 3)["recent"] == 1
    assert campaign_summary(groups, 0)["recent"] == 0
    assert campaign_summary({"empty": []}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}
    assert campaign_summary({}, 5) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_groups_excludes_empty_and_breaks_ties_by_name():
    groups = {"z": [session("z", 1, True)], "empty": [],
              "a": [session("a", 1, True)], "b": [session("b", 1, False)]}
    assert top_converting_groups(groups, 10) == ["a", "z", "b"]
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 0) == []


def test_rate_by_group_sorted_with_none_for_empty():
    groups = {"z": [], "b": [session("b", 1, None)], "a": [session("a", 1, True)]}
    rates = conversion_rate_by_group(groups)
    assert list(rates) == ["a", "b", "z"]
    assert rates == {"a": 1.0, "b": 0.0, "z": None}


def test_longest_streak_resets_on_nonpositive_entries():
    assert longest_conversion_streak([1, 1, 0, 1, -1, 1, 2, 3]) == 3
    assert longest_conversion_streak([-2, 0, -1]) == 0
    assert longest_conversion_streak([]) == 0
